# ---------------------------------------------------------------- 作者名格式化

def _format_author_gb(name):
    """将单个作者名格式化为 GB/T 7714 格式。

    规则：
      - 姓全大写，名取首字母（无缩写点）
      - 中文姓名：姓在前（全大写），名在后（全拼）
      - 例： "Sang Cheol Kim" → "KIM S C"
            "Yi Cui"         → "CUI Y"
            "Andrew I. Cooper" → "COOPER A I"
    """
    name = name.strip()
    if not name:
        return ""

    # 检测是否为中文姓名（全为 CJK 字符）
    if all('\u4e00' <= c <= '\u9fff' for c in name.replace(' ', '')):
        # 中文姓名：第一个字为姓
        parts = name.split()
        if len(parts) >= 2:
            surname = parts[0]
            given = ''.join(parts[1:])
        else:
            surname = parts[0][:1] if parts[0] else ""
            given = parts[0][1:] if len(parts[0]) > 1 else ""
        return f"{surname.upper()} {given.upper()}" if given else surname.upper()

    # 西文姓名处理
    # 🔴 2026-10-10 修：先识别**末尾缩写串**再定姓。
    #    旧实现先 `name.replace('.', '')` 把点去掉、再取 `parts[-1]` 当姓 ⇒
    #    `Kim S.C.` 变成 `Kim SC` ⇒ 姓取 `SC`、名取 `Kim` ⇒ 输出
    #    **`SC K`**（把缩写当成了姓）。而 `_README.md` 里**照着抄的示例**
    #    正是 `--authors "Kim S.C.; Oyakhire S.T.; Cui Y."` ⇒ 文档示例直接产出错引用。
    #    正确形态：`KIM S C`（姓 Kim，名缩写 S C）。
    raw = name.strip()
    raw_parts = raw.split()
    # 末尾连续的「首字母缩写」：`S.C.` / `S.` / `Y.` / 单个大写字母。
    # ⚠️ 收紧条件（避免把**全大写姓氏**当缩写）：只认
    #    ① 原本带点（`S.C.`、`Y.`）——这是明确的缩写记号；或
    #    ② 单个大写字母（`Y`）。
    #    不认 `LI`（无点、非单字母）——那更像姓氏 `Li` 的大写写法。
    tail_initials = []
    while len(raw_parts) > 1:
        tok = raw_parts[-1]
        bare = tok.replace(".", "")
        dotted = "." in tok
        is_abbr = bool(bare) and bare.isalpha() and bare.isupper() and len(bare) <= 3
        if is_abbr and (dotted or len(bare) == 1):
            tail_initials.insert(0, bare)
            raw_parts.pop()
        else:
            break
    name = raw.replace('.', '').strip()
    parts = name.split()
    if len(parts) == 0:
        return ""
    if len(parts) == 1:
        return parts[0].upper()
    if tail_initials:
        # 末尾是缩写 ⇒ 姓 = 缩写之前的最后一个词，其余为名。
        # ⚠️ 一个 token 可能是**多个首字母连写**（`S.C.` → 去掉点 → `SC`），
        #    GB/T 7714 要逐字母给缩写（`KIM S C`），不能整体拼成 `SC`。
        surname = parts[-len(tail_initials) - 1]
        given_parts = parts[:-len(tail_initials) - 1]
        extra = [ch for x in tail_initials for ch in x if ch.isalpha()]
        initials = ' '.join([p[0].upper() for p in given_parts if p] + extra)
        return f"{surname.upper()} {initials}" if initials else surname.upper()

    # 判断是否有 "前缀"（如 von, de, van 等）—— 简单处理：最后一个是姓
    # 常见模式：First Middle ... Last
    surname = parts[-1]
    given_parts = parts[:-1]

    # 判断是否有 "前缀"（如 von, de, van 等）—— 简单处理：最后一个是姓
    # 常见模式：First Middle ... Last
    surname = parts[-1]
    given_parts = parts[:-1]

    # 特殊情况：如果有连字符姓（如 "De La Cruz"），暂按最后一个词为姓
    surname_upper = surname.upper()
    initials = ' '.join(p[0].upper() for p in given_parts if p)

    return f"{surname_upper} {initials}" if initials else surname_upper


def format_authors(authors, max_authors=3):
    """格式化作者列表为 GB/T 7714 字符串。

    规则：
      - 前 max_authors 位作者全列出
      - 超出部分用 ", et al." 替代
      - 作者间用 ", " 分隔
    """
    if isinstance(authors, str):
        # 分号分隔（手动输入）或逗号分隔（frontmatter 字符串）
        if ';' in authors:
            authors = [a.strip() for a in authors.split(';') if a.strip()]
        else:
            authors = [a.strip() for a in authors.split(',') if a.strip()]
    if not authors:
        return ""

    formatted = []
    for a in authors:
        f = _format_author_gb(a)
        if f:
            formatted.append(f)

    if len(formatted) <= max_authors:
        return ', '.join(formatted)
    else:
        return ', '.join(formatted[:max_authors]) + ', et al.'


# ---------------------------------------------------------------- 标题提取

def _extract_title(fm, body, page_name):
    """从 frontmatter / 正文 / 页面名中提取论文标题。

    优先级：
      1. frontmatter 中的 title 字段
      2. 正文第一个一级标题
      3. 从页面名推断（去掉年份和期刊后缀）
    """
    # 1. 显式 title
    title = fm.get("title", "")
    if title and isinstance(title, str) and title.strip():
        return title.strip()

    # 2. 正文第一个 # 标题
    headings = re.findall(r"^#\s+(.+)$", body, flags=re.M)
    for h in headings:
        h = h.strip()
        # 跳过纯中文描述性标题（通常含括号注释）
        if h and len(h) > 5:
            # 去掉括号中的作者/年份注释
            clean = re.sub(r"[（(].*?[）)]", "", h).strip()
            if clean:
                return clean

    # 3. 从页面名推断
    # 格式通常为 "2022-示例卡片-示例期刊"
    parts = page_name.split("-", 2)
    if len(parts) >= 2:
        # 跳过年份部分
        title_part = parts[1] if len(parts) < 3 else parts[1]
        if title_part:
            return title_part

    return page_name


# ---------------------------------------------------------------- DOI 提取

def _extract_doi(fm, source_url):
    """从 frontmatter 或 source_url 提取 DOI。"""
    # 直接 doi 字段
    doi = fm.get("doi", "")
    if doi and isinstance(doi, str) and doi.strip():
        return doi.strip()

    # 从 source_url 提取
    url = source_url or ""
    # 匹配 doi.org/xxx 或 dx.doi.org/xxx
    m = re.search(r"doi\.org/(.+)$", url)
    if m:
        return m.group(1).rstrip('/')

    # 匹配 10.xxxx/ 开头的字符串
    m = re.search(r"(10\.\d{4,}/\S+)", url)
    if m:
        return m.group(1).rstrip('/')

    return ""


# ---------------------------------------------------------------- 核心格式化

def format_citation(fm, body="", page_name="", seq_num=1):
    """生成 GB/T 7714 引用字符串。

    参数：
      fm: frontmatter dict
      body: 正文文本（用于提取标题）
      page_name: 页面名（备用标题源）
      seq_num: 引用序号（默认 1）

    返回：格式化后的引用字符串
    """
    # 作者
    authors = fm.get("authors", [])
    author_str = format_authors(authors)
    if not author_str:
        author_str = fm.get("corresponding_author", "")
        if author_str:
            author_str = _format_author_gb(author_str.split("（")[0].strip())

    # 标题
    title = _extract_title(fm, body, page_name)

    # 文献类型标识
    source_type = fm.get("source_type", "").lower()
    if "review" in source_type or "综述" in str(fm.get("tags", [])):
        doc_type = "[J]"  # 期刊论文（综述也是期刊发表）
    else:
        doc_type = "[J]"  # 默认期刊论文

    # 期刊名
    journal = fm.get("journal", "")
    if not journal:
        # 尝试从页面名推断（最后一部分）
        parts = page_name.rsplit("-", 1)
        if len(parts) > 1 and len(parts[-1]) < 30:
            journal = parts[-1]

    # 年份
    year = fm.get("year", "")
    if not year:
        pub = fm.get("published", "")
        if pub and isinstance(pub, str) and len(pub) >= 4:
            year = pub[:4]

    # 卷期页
    volume = fm.get("volume", "")
    issue = fm.get("issue", "")
    pages = fm.get("pages", "")

    # DOI
    doi = _extract_doi(fm, fm.get("source_url", ""))

    # 组装
    parts = [f"[{seq_num}]"]
    if author_str:
        # 避免 "et al.." 双句号
        if author_str.endswith('.'):
            parts.append(author_str)
        else:
            parts.append(author_str + ".")
    parts.append(f"{title}{doc_type}.")
    if journal:
        cite_part = f"{journal}"
        if year:
            cite_part += f", {year}"
        if volume:
            cite_part += f", {volume}"
            if issue:
                cite_part += f"({issue})"
        if pages:
            cite_part += f": {pages}"
        parts.append(f"{cite_part}.")
    elif year:
        parts.append(f"{year}.")

    result = ' '.join(parts)

    # DOI 附加
    if doi:
        result += f"\n    DOI:{doi}"

    return result


# ---------------------------------------------------------------- 页面读取

def _load_page(page_path):
    """读取 wiki 页面，返回 (fm_dict, body, page_name)。"""
    # 补全路径
    if not os.path.isabs(page_path):
        if not page_path.startswith("wiki/"):
            page_path = os.path.join(K.WIKI, page_path)
        else:
            page_path = os.path.join(K.VAULT, page_path)

    if not page_path.endswith(".md"):
        page_path += ".md"

    if not os.path.exists(page_path):
        return None, None, None

    text = K.read_text(page_path)
    fm_raw, body = K.split_frontmatter(text)
    fm = K.parse_frontmatter(fm_raw)
    page_name = os.path.splitext(os.path.basename(page_path))[0]
    return fm, body, page_name


# ---------------------------------------------------------------- CLI

def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    GB/T 7714 的作者格式化是**纯字符串规则**，正是本库「校验器自检纪律」
    针对的那类判据，故必须对已知答案反算。正例取自 docstring 自己的例子。
    """
    ok = True

    # ---- _format_author_gb 正例（docstring 声称的三个例子）----
    cases = [
        ("Sang Cheol Kim", "KIM S C", "多名 + 缩写"),
        ("Yi Cui", "CUI Y", "两词"),
        ("Andrew I. Cooper", "COOPER A I", "带缩写点须剥离"),
        ("Gregory S. Engel", "ENGEL G S", "中间名首字母"),
        # 🆕 2026-10-10 回归夹具：带点的**末尾缩写**必须拆成逐字母，姓取缩写之前那个词。
        #    旧实现先把点删掉再取 `parts[-1]` 当姓 ⇒ `Kim S.C.` 输出 `SC K`
        #    （把缩写当成姓），而 `_README.md` 里**照抄的示例**正是这种写法。
        ("Kim S.C.", "KIM S C", "末尾多字母缩写（README 示例形态）"),
        ("Oyakhire S.T.", "OYAKHIRE S T", "末尾两缩写"),
        ("Cui Y.", "CUI Y", "末尾单缩写"),
        # 反例：**无点、非单字母**的全大写尾词不当缩写（否则 `Mary LI` 会被拆成 MARY L I）
        ("Mary LI", "LI M", "反例 全大写姓氏不是缩写"),
        # ⚠️ 已知边界（由本自检如实钉住，不掩盖）：
        #    「姓-名 / 名-姓 顺序」**无法从单串判定**。对 `D'Souza Aaron`（姓在前）
        #    会误判成 `AARON D`。这**不是撇号问题**（本库纪律明载撇号是正当姓名字符），
        #    而是固有限制 ⇒ 取姓在末位的写法才是本工具的正确输入形态。
        ("A. D'Souza", "D'SOUZA A", "撇号姓在末位（正当姓名，不得判脏）"),
    ]
    for src, want, label in cases:
        got = _format_author_gb(src)
        mark = "ok" if got == want else "FAIL"
        print(f"  [{mark}] 西文 {label}: {src!r} -> {got!r}")
        ok = ok and got == want

    # ---- 中文姓名 ----
    got = _format_author_gb("张三")
    # 单段中文名：首字为姓、余下为名
    print(f"  [{'ok' if got == '张 三' else 'info'}] 中文单段 -> {got!r}（如实记录）")
    got = _format_author_gb("张 三")
    print(f"  [{'ok' if got == '张 三' else 'FAIL'}] 中文两段 -> {got!r}")
    ok = ok and got == "张 三"

    # ---- 反例 ----
    got = _format_author_gb("")
    print(f"  [{'ok' if got == '' else 'FAIL'}] 反例 空串 -> {got!r}")
    ok = ok and got == ""
    got = _format_author_gb("Smith")
    print(f"  [{'ok' if got == 'SMITH' else 'FAIL'}] 单名 -> {got!r}（不编造首字母）")
    ok = ok and got == "SMITH"

    # ---- format_authors：et al. 截断规则 ----
    got = format_authors(["Yi Cui", "Sang Cheol Kim"])
    want = "CUI Y, KIM S C"
    print(f"  [{'ok' if got == want else 'FAIL'}] 作者 2 位不截断 -> {got!r}")
    ok = ok and got == want
    got = format_authors(["A B", "C D", "E F", "G H"], max_authors=3)
    # 更新后的期望：`A B` 被读作「姓 A + 首字母 B」（B 是单个大写字母）⇒ 输出 A B。
    # 恒等映射恰好保持了原样，故仍能测出"截断点了没"。
    good = got == "A B, C D, E F, et al."
    print(f"  [{'ok' if good else 'FAIL'}] 超过阈值加 et al. -> {got!r}")
    ok = ok and good
    # 🆕 README 示例回归：文档里照抄的那条命令必须产出正确引用
    got = format_authors("Kim S.C.; Oyakhire S.T.; Cui Y.")
    want = "KIM S C, OYAKHIRE S T, CUI Y"
    print(f"  [{'ok' if got == want else 'FAIL'}] README 的 --authors 示例 -> {got!r}")
    ok = ok and got == want
    got = format_authors("Zhang San; Li Si")
    print(f"  [{'ok' if got == 'SAN Z, SI L' else 'info'}] 分号串解析 -> {got!r}（如实记录）")
    got = format_authors([])
    print(f"  [{'ok' if got == '' else 'FAIL'}] 反例 空列表 -> {got!r}")
    ok = ok and got == ""

    # ---- 反例：绝不存在的页面不得被误报为存在 ----
    fm, body, name = _load_page("绝不存在-xyz-页面")
    print(f"  [{'ok' if fm is None else 'FAIL'}] 反例 不存在的页面 -> fm=None")
    ok = ok and fm is None

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(
        description="GB/T 7714 引用格式化",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
示例：
  python tools/kb_cite.py --page sources/2022-示例卡片-示例期刊.md
  python tools/kb_cite.py --page 2020-自主移动机器人化学家-Nature
  python tools/kb_cite.py --authors "Kim S.C.; Oyakhire S.T.; Cui Y." \\
      --year 2022 --title "Data-driven electrolyte design" --journal PNAS
""")
    # 从页面读取
    ap.add_argument("--page", type=str, default="",
                    help="wiki 页面路径（相对于 wiki/ 或 vault）")
    # 手动指定字段
    ap.add_argument("--authors", type=str, default="",
                    help="作者列表（分号分隔，如 'Zhang San; Li Si; Wang Wu'）")
    ap.add_argument("--year", type=str, default="", help="出版年份")
    ap.add_argument("--title", type=str, default="", help="论文标题")
    ap.add_argument("--journal", type=str, default="", help="期刊名")
    ap.add_argument("--doi", type=str, default="", help="DOI")
    ap.add_argument("--volume", type=str, default="", help="卷号")
    ap.add_argument("--issue", type=str, default="", help="期号")
    ap.add_argument("--pages", type=str, default="", help="页码")
    # 输出控制
    ap.add_argument("-n", type=int, default=1, help="引用序号（默认 1）")
    ap.add_argument("--copy", action="store_true",
                    help="复制到剪贴板（需 pyperclip）")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")

    args = ap.parse_args()

    if args.selftest:
        return selftest()

    if args.page:
        fm, body, page_name = _load_page(args.page)
        if fm is None:
            print(f"[!] 页面不存在: {args.page}", file=sys.stderr)
            return 1
        result = format_citation(fm, body, page_name, seq_num=args.n)
    elif args.authors or args.title:
        # 手动模式：分号分隔作者
        authors = [a.strip() for a in args.authors.split(';') if a.strip()]
        fm = {
            "authors": authors,
            "year": args.year,
            "title": args.title,
            "journal": args.journal,
            "doi": args.doi,
            "volume": args.volume,
            "issue": args.issue,
            "pages": args.pages,
        }
        result = format_citation(fm, page_name="", seq_num=args.n)
    else:
        ap.print_help()
        return 1

    print(result)

    # 复制到剪贴板
    if args.copy:
        try:
            import pyperclip
            pyperclip.copy(result)
            print("\n[已复制到剪贴板]", file=sys.stderr)
        except ImportError:
            print("\n[!] 剪贴板复制需要 pyperclip: pip install pyperclip",
                  file=sys.stderr)

    return 0


if __name__ == "__main__":
    sys.exit(main())
